package com.example.starter.ct;

import java.util.List;

/**
 * RFC 6962 风格的 Merkle 树哈希与证明工具（纯函数，无状态）。
 *
 * <p>哈希规则固定：叶节点 {@code SHA-256(0x00 || leafBytes)}，
 * 内部节点 {@code SHA-256(0x01 || left || right)}；奇数节点不复制，
 * 按标准递归分割（k 为小于 n 的最大 2 的幂）计算。</p>
 */
public final class MerkleTree {

    private MerkleTree() {
    }

    /**
     * 计算叶节点哈希：SHA-256(0x00 || leafBytes)。
     */
    public static byte[] leafHash(byte[] leafBytes) {
        throw new UnsupportedOperationException("not implemented");
    }

    /**
     * 计算叶哈希列表 [from, to) 区间的 Merkle 根。
     */
    public static byte[] rootHash(List<byte[]> leafHashes, int from, int to) {
        throw new UnsupportedOperationException("not implemented");
    }

    /**
     * 生成叶索引 index 在整棵树（大小为 leafHashes.size()）下的包含证明（审计路径）。
     */
    public static List<byte[]> auditPath(List<byte[]> leafHashes, int index) {
        throw new UnsupportedOperationException("not implemented");
    }

    /**
     * 生成树大小 first 到 second（0 &lt; first &lt;= second）的一致性证明。
     */
    public static List<byte[]> consistencyPath(List<byte[]> leafHashes, int first, int second) {
        throw new UnsupportedOperationException("not implemented");
    }

    /**
     * 本地验证包含证明，返回计算出的根哈希（调用方与期望根比较）。
     */
    public static byte[] verifyInclusion(byte[] leafHash, long leafIndex, long treeSize, List<byte[]> auditPath) {
        throw new UnsupportedOperationException("not implemented");
    }

    /**
     * 本地验证一致性证明：由 firstRoot、secondRoot 与路径重放，返回是否同时匹配两个根。
     */
    public static boolean verifyConsistency(long first, long second, byte[] firstRoot, byte[] secondRoot,
            List<byte[]> consistencyPath) {
        throw new UnsupportedOperationException("not implemented");
    }
}

package com.example.starter.ct;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带稳定错误码与 HTTP 状态，由全局异常处理器转换为统一错误响应。
 */
public class CtException extends RuntimeException {

    private final HttpStatus status;
    private final String code;

    public CtException(HttpStatus status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public HttpStatus status() {
        return status;
    }

    public String code() {
        return code;
    }

    public static CtException badRequest(String code, String message) {
        return new CtException(HttpStatus.BAD_REQUEST, code, message);
    }

    public static CtException conflict(String code, String message) {
        return new CtException(HttpStatus.CONFLICT, code, message);
    }

    public static CtException unauthorized(String code, String message) {
        return new CtException(HttpStatus.UNAUTHORIZED, code, message);
    }
}

package com.example.starter.ct;

import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Component;

/**
 * 证书透明日志配置。
 */
@Component
@ConfigurationProperties(prefix = "ct")
public class CtProperties {

    private final Observer observer = new Observer();

    public Observer getObserver() {
        return observer;
    }

    /**
     * 观察者验签配置。
     */
    public static class Observer {

        /** 合成 Ed25519 公钥（X.509，Base64）；为空时验签服务不可用。 */
        private String publicKey = "";

        public String getPublicKey() {
            return publicKey;
        }

        public void setPublicKey(String publicKey) {
            this.publicKey = publicKey;
        }
    }
}

